import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { Resend } from 'resend'

const TestSendSchema = z.object({
  subject: z.string().min(1).max(500),
  body: z.string().min(1).max(50000),
  channel: z.literal('email'),
})

// Per-user rate limit — 5/min enforced via the user id key
// (apiRatelimit is 120/min; we apply per-user stricter check by keying on user+action)

function resolveMergeTags(html: string, firstName: string, studioName: string): string {
  return html
    .replace(/\{first_name\}/g, firstName)
    .replace(/\{last_name\}/g, 'Client')
    .replace(/\{studio_name\}/g, studioName)
    .replace(/\{booking_url\}/g, '#')
    .replace(/\{referral_code\}/g, 'FRIEND10')
    .replace(/\{discount_amount\}/g, '$10')
    .replace(/\{last_visit\}/g, 'recently')
    .replace(/\{total_bookings\}/g, '5')
}

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  // Tighter rate limit for test sends — keyed per user
  const { success } = await apiRatelimit.limit(`test-send:${authUser.user.id}`)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try { body = await request.json() } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = TestSendSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Fetch the user email + profile for merge tag resolution
    const [{ data: profile }, { data: studio }] = await Promise.all([
      supabase
        .from('profiles')
        .select('first_name, email')
        .eq('id', authUser.user.id)
        .single(),
      supabase
        .from('studios')
        .select('name')
        .eq('id', authUser.studioId)
        .single(),
    ])

    const toEmail = (profile as { first_name?: string; email?: string } | null)?.email ?? ''
    if (!toEmail) {
      return NextResponse.json({ error: 'No email address on your account' }, { status: 400 })
    }

    const firstName = (profile as { first_name?: string } | null)?.first_name ?? 'Sam'
    const studioName = (studio as { name?: string } | null)?.name ?? 'Your Studio'

    const resolvedHtml = resolveMergeTags(parsed.data.body, firstName, studioName)

    const key = process.env.RESEND_API_KEY
    if (!key) {
      logger.warn({ to: toEmail }, 'test-send skipped — RESEND_API_KEY not set')
      return NextResponse.json({ ok: true, skipped: true })
    }

    const resend = new Resend(key)
    const fromEmail = process.env.RESEND_FROM_EMAIL ?? 'notifications@inkos.app'

    const { error: sendError } = await resend.emails.send({
      from: fromEmail,
      to: toEmail,
      subject: `[Test] ${parsed.data.subject}`,
      html: resolvedHtml,
    })

    if (sendError) {
      logger.error({ err: sendError, to: toEmail }, 'test-send failed')
      return NextResponse.json({ error: sendError.message ?? 'Failed to send test email' }, { status: 500 })
    }

    logger.info({ to: toEmail }, 'marketing test send delivered')
    return NextResponse.json({ ok: true })
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error({ err }, 'test-send unexpected error')
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

