    }

    const toEmail = (profile as { first_name?: string; email?: string } | null)?.email ?? ''
    if (!toEmail) {
      return NextResponse.json({ error: 'No email address on your account' }, { status: 400 })
    }

    const firstName = (profile as { first_name?: string } | null)?.first_name ?? 'Sam'
    const studioName = (studio as { name?: string } | null)?.name ?? 'Your Studio'
    const subject = campaign.template_subject ?? '(no subject)'
    const body = campaign.template_body ?? '<p>(empty body)</p>'

    const resolvedHtml = resolveMergeTags(body, firstName, studioName)

    const key = process.env.RESEND_API_KEY
    if (!key) {
      logger.warn({ to: toEmail, campaignId }, 'test-send skipped — RESEND_API_KEY not set')
      return NextResponse.json({ ok: true, skipped: true })
    }

    const resend = new Resend(key)
    const fromEmail = process.env.RESEND_FROM_EMAIL ?? 'notifications@inkos.app'

    const { error: sendError } = await resend.emails.send({
      from: fromEmail,
      to: toEmail,
      subject: `[Test] ${subject}`,
      html: resolvedHtml,
    })

    if (sendError) {
      logger.error({ err: sendError, to: toEmail, campaignId }, 'test-send failed')
      return NextResponse.json({ error: sendError.message ?? 'Failed to send test email' }, { status: 500 })
    }

    logger.info({ to: toEmail, campaignId }, 'marketing test send delivered')
    return NextResponse.json({ ok: true })
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error({ err }, 'campaign test-send unexpected error')
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

'use client'

import { useEffect, useState } from 'react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type SegmentSlug =
  | 'all'
  | 'inactive_90d'
  | 'new_30d'
  | 'top_spenders'
  | 'birthday_month'
  | 'booked_next_14d'
  | 'unsubscribed'

interface SegmentCounts {
  all: number
  inactive_90d: number
  new_30d: number
  top_spenders: number
  birthday_month: number
  booked_next_14d: number
  unsubscribed: number
}

const SEGMENTS: Array<{ slug: SegmentSlug; label: string; description: string }> = [
  { slug: 'all',            label: 'All clients',          description: 'Everyone in your CRM' },
  { slug: 'inactive_90d',   label: 'Inactive 90 days',     description: 'No visit in 90 days' },
  { slug: 'new_30d',        label: 'New (last 30 days)',    description: 'First visit this month' },
  { slug: 'top_spenders',   label: 'Top spenders',         description: 'Top 20% by lifetime spend' },
  { slug: 'birthday_month', label: 'Birthday this month',  description: 'Birthdays this calendar month' },
  { slug: 'booked_next_14d',label: 'Booked next 14 days',  description: 'Upcoming appointments' },
  { slug: 'unsubscribed',   label: 'Unsubscribed',         description: 'Opted out of marketing' },
]

interface SegmentPresetChipsProps {
  activeSlug?: SegmentSlug | null
  onSelect: (slug: SegmentSlug) => void
  className?: string
}

export function SegmentPresetChips({ activeSlug, onSelect, className }: SegmentPresetChipsProps) {
  const [counts, setCounts] = useState<Partial<SegmentCounts>>({})
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    fetch('/api/marketing/segments')
      .then((r) => r.json())
      .then((json: unknown) => {
        if (cancelled) return
        if (json && typeof json === 'object' && 'data' in json) {
          setCounts((json as { data: Partial<SegmentCounts> }).data ?? {})
        }
      })
      .catch(() => {
        // non-blocking — counts just won't show
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => { cancelled = true }
  }, [])

  return (
    <div className={cn('flex flex-wrap gap-2', className)} role="group" aria-label="Audience segment presets">
      {SEGMENTS.map(({ slug, label, description }) => {
        const count = counts[slug]
        const isActive = activeSlug === slug

        return (
          <Button
            key={slug}
            type="button"
            variant="outline"
            size="sm"
            aria-label={`${label}${count !== undefined ? `, ${count} clients` : ''}`}
            aria-pressed={isActive}
            onClick={() => onSelect(slug)}
            className={cn(
              'h-8 gap-1.5 text-xs font-normal transition-colors',
              isActive
                ? 'bg-[color:var(--color-onyx)] text-[color:var(--color-bone)] border-[color:var(--color-onyx)] hover:bg-[color:var(--color-onyx)]/90'
                : 'bg-[color:var(--color-bone)] hover:bg-[color:var(--color-onyx)]/5',
              // Unsubscribed chip is subtle — exclude action, not target
              slug === 'unsubscribed' && !isActive && 'opacity-60',
            )}
            title={description}
          >
            {label}
            {count !== undefined && !loading && (
              <span
                className={cn(
                  'inline-flex items-center justify-center rounded-full px-1.5 py-0 text-[10px] font-semibold tabular-nums min-w-[18px]',
                  isActive
                    ? 'bg-white/20 text-white'
                    : 'bg-[color:var(--color-stone)]/15 text-[color:var(--color-stone)]',
                  // Rust count badge on inactive_90d only (one Rust accent, earned)
                  slug === 'inactive_90d' && !isActive && 'bg-[color:var(--color-rust)]/10 text-[color:var(--color-rust)]',
                )}
              >
                {count.toLocaleString()}
              </span>
            )}
          </Button>
        )
      })}
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

interface MarketingTemplate {
  id: string
  name: string
  description: string | null
  subject_template: string
  body_template: string
  recommended_segment: string | null
  display_order: number
}

export interface TemplateSelection {
  subject: string
  body: string
  recommendedSegment: string | null
}

interface TemplateGalleryProps {
  onSelect: (selection: TemplateSelection) => void
  className?: string
}

export function TemplateGallery({ onSelect, className }: TemplateGalleryProps) {
  const [templates, setTemplates] = useState<MarketingTemplate[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [selectedId, setSelectedId] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    fetch('/api/marketing/templates')
      .then((r) => r.json())
      .then((json: unknown) => {
        if (cancelled) return
        if (json && typeof json === 'object' && 'data' in json) {
          setTemplates((json as { data: MarketingTemplate[] }).data ?? [])
        }
      })
      .catch(() => {
        if (!cancelled) setError('Failed to load templates')
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => { cancelled = true }
  }, [])

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-3 text-xs text-muted-foreground">
        <Loader2 className="h-3.5 w-3.5 animate-spin" />
        Loading templates...
      </div>
    )
  }

  if (error) {
    return <p className="py-2 text-xs text-destructive">{error}</p>
  }

  if (templates.length === 0) {
    return <p className="py-2 text-xs text-muted-foreground">No templates available.</p>
  }

  function handleSelect(t: MarketingTemplate) {
    setSelectedId(t.id)
    onSelect({
      subject: t.subject_template,
      body: t.body_template,
      recommendedSegment: t.recommended_segment,
    })
  }

  return (
    <div className={cn('grid gap-2 sm:grid-cols-2 lg:grid-cols-3', className)}>
      {templates.map((t) => (
        <div
          key={t.id}
          className={cn(
            'rounded-lg border bg-[color:var(--color-bone)] p-3 shadow-soft flex flex-col gap-2 transition-shadow hover:shadow-card',
            selectedId === t.id && 'ring-1 ring-[color:var(--color-onyx)]',
          )}
        >
          <div className="space-y-0.5">
            <p className="text-xs font-semibold text-[color:var(--color-onyx)] leading-snug">{t.name}</p>
            {t.description && (
              <p className="text-[11px] text-[color:var(--color-stone)] leading-relaxed">{t.description}</p>
            )}
          </div>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-7 text-xs mt-auto"
            onClick={() => handleSelect(t)}
          >
            Use template
          </Button>
        </div>
      ))}
    </div>
  )
}
